import React, { useState } from "react";

function App() {
  const [darkMode, setDarkMode] = useState(false);
  const [ingredients, setIngredients] = useState("");
  const [mealType, setMealType] = useState("Breakfast");
  const [cuisine, setCuisine] = useState("");
  const [cookingTime, setCookingTime] = useState("Less than 30 minutes");
  const [complexity, setComplexity] = useState("Beginner");
  const [result, setResult] = useState("");

  const handleSubmit = async () => {
    const response = await fetch("http://localhost:5000/generate-recipe", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ ingredients, mealType, cuisine, cookingTime, complexity })
    });
    const data = await response.json();
    setResult(data.recipe);
  };

  return (
    <div className={`${darkMode ? "dark" : ""}`}>
      <div className="min-h-screen bg-white dark:bg-gray-900 text-gray-900 dark:text-white p-4">
        <div className="flex justify-end mb-4">
          <button onClick={() => setDarkMode(!darkMode)} className="p-2">
            {darkMode ? (
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m8.66-8.66l-.71.71M4.05 4.05l.71.71M21 12h-1M4 12H3m16.95 4.95l-.71-.71M4.05 19.95l.71-.71M12 5a7 7 0 000 14a7 7 0 000-14z" /></svg>
            ) : (
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="currentColor" stroke="none"><path d="M12 2a1 1 0 0 1 1 1v2a1 1 0 1 1-2 0V3a1 1 0 0 1 1-1zm0 17a5 5 0 1 0 0-10 5 5 0 0 0 0 10z" /></svg>
            )}
          </button>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 max-w-5xl mx-auto">
          <div className="bg-gray-100 dark:bg-gray-800 rounded-xl p-6 shadow-md">
            <h2 className="text-2xl font-bold mb-4 text-center">Recipe Generator</h2>
            <div className="space-y-4">
              <input className="w-full p-2 rounded border" placeholder="Ingredients" value={ingredients} onChange={(e) => setIngredients(e.target.value)} />
              <select className="w-full p-2 rounded border" value={mealType} onChange={(e) => setMealType(e.target.value)}>
                <option>Breakfast</option><option>Lunch</option><option>Dinner</option><option>Snack</option>
              </select>
              <input className="w-full p-2 rounded border" placeholder="Cuisine" value={cuisine} onChange={(e) => setCuisine(e.target.value)} />
              <select className="w-full p-2 rounded border" value={cookingTime} onChange={(e) => setCookingTime(e.target.value)}>
                <option>Less than 30 minutes</option><option>30-60 minutes</option><option>More than 1 hour</option>
              </select>
              <select className="w-full p-2 rounded border" value={complexity} onChange={(e) => setComplexity(e.target.value)}>
                <option>Beginner</option><option>Intermediate</option><option>Advanced</option>
              </select>
              <button onClick={handleSubmit} className="w-full bg-blue-600 text-white p-2 rounded hover:bg-blue-700">Generate Recipe</button>
            </div>
          </div>
          <div className="bg-gray-100 dark:bg-gray-800 rounded-xl p-6 shadow-md whitespace-pre-wrap">{result}</div>
        </div>
      </div>
    </div>
  );
}

export default App;
